#!/usr/bin/env python3
"""The Passport Page of a Country That Isn't There.

Writes one image -- an invented passport spread for the Republic of
Aldermere, a North Atlantic island nation that does not exist -- to
/output/entry.png.

The spread was composed in this repository's build session (see
draw_passport.py): a photographic portrait composited with a fully drawn
data page (personal data and a valid ICAO machine-readable zone, issue
02 FEB 2024, expiry 01 FEB 2034) and a visa page whose stamps tell one
plausible travel history -- Bergen, Torshavn, Reykjavik, and home to
Skardvik -- plus the one telling detail of paperwork: Condition 7, the
holder must declare all wool and down on arrival.

The program ships the finished spread as an embedded PNG and writes it
out, checking the gate (a whole PNG, at most 1 MiB, at most 1024x1024)
before it lands. Standard library only, no network.
"""
import base64
import binascii
import hashlib
import os
import struct
import sys

